param([string]$Destination = "local/ps3recomp")\n\n$ErrorActionPreference = "Stop"\n$Pin = "e2815326c58d3530936166982672cb09acdef4f9"\n$Repo = "https://github.com/sp00nznet/ps3recomp.git"\n\nif (-not (Get-Command git -ErrorAction SilentlyContinue)) { throw "git is required" }\nif (-not (Get-Command python -ErrorAction SilentlyContinue)) { throw "python is required" }\n\nif (-not (Test-Path $Destination)) {\n    $Parent = Split-Path $Destination -Parent\n    if ($Parent) { New-Item -ItemType Directory -Force -Path $Parent | Out-Null }\n    git clone $Repo $Destination\n}\n\ngit -C $Destination fetch origin\ngit -C $Destination checkout --detach $Pin\n$Observed = (git -C $Destination rev-parse HEAD).Trim()\nif ($Observed -ne $Pin) { throw "ps3recomp pin mismatch: $Observed" }\n\n$Req = Join-Path $Destination "requirements.txt"\nif (-not (Test-Path $Req)) { $Req = Join-Path $Destination "tools\requirements.txt" }\nif (Test-Path $Req) { python -m pip install -r $Req }\n\nWrite-Host ""\nWrite-Host "ps3recomp ready at $Destination"\nWrite-Host "revision: $Observed"\nWrite-Host "For Windows M2 builds, CMake, Ninja, Visual Studio C++ tools and clang-cl must be available."\n